alter table public.ai_council_runs add column if not exists created_by uuid; create policy "members_insert_ai_council_runs" on public.ai_council_runs for insert to authenticated with check (public.is_workspace_member(auth.uid(), workspace_id) and (created_by is null or created_by = auth.uid())); create policy "members_update_own_ai_council_runs" on public.ai_council_runs for update to authenticated using (public.is_workspace_member(auth.uid(), workspace_id) and (created_by is null or created_by = auth.uid())) with check (public.is_workspace_member(auth.uid(), workspace_id) and (created_by is null or created_by = auth.uid()));;
